// StyleDefinition preserves all public excelize.Style fields with typed categorical values.
type StyleDefinition struct {
	Border        []BorderDefinition
	Fill          FillDefinition
	Font          *FontDefinition
	Alignment     *AlignmentDefinition
	Protection    *ProtectionDefinition
	NumFmt        NumberFormat
	DecimalPlaces *int
	CustomNumFmt  *string
	NegRed        bool
}

func (in StyleDefinition) ToExcelize() excelize.Style {
	out := excelize.Style{}
	if in.Border != nil {
		out.Border = make([]excelize.Border, len(in.Border))
		for i, value := range in.Border {
			out.Border[i] = value.ToExcelize()
		}
	}
	out.Fill = in.Fill.ToExcelize()
	if in.Font != nil {
		value := in.Font.ToExcelize()
		out.Font = &value
	}
	if in.Alignment != nil {
		value := in.Alignment.ToExcelize()
		out.Alignment = &value
	}
	if in.Protection != nil {
		value := in.Protection.ToExcelize()
		out.Protection = &value
	}
	out.NumFmt = int(in.NumFmt)
	out.DecimalPlaces = in.DecimalPlaces
	out.CustomNumFmt = in.CustomNumFmt
	out.NegRed = in.NegRed
	return out
}
func StyleDefinitionFromExcelize(in excelize.Style) StyleDefinition {
	out := StyleDefinition{}
	if in.Border != nil {
		out.Border = make([]BorderDefinition, len(in.Border))
		for i, value := range in.Border {
			out.Border[i] = BorderDefinitionFromExcelize(value)
		}
	}
	out.Fill = FillDefinitionFromExcelize(in.Fill)
	if in.Font != nil {
		value := FontDefinitionFromExcelize(*in.Font)
		out.Font = &value
	}
	if in.Alignment != nil {
		value := AlignmentDefinitionFromExcelize(*in.Alignment)
		out.Alignment = &value
	}
	if in.Protection != nil {
		value := ProtectionDefinitionFromExcelize(*in.Protection)
		out.Protection = &value
	}
	out.NumFmt = NumberFormat(in.NumFmt)
	out.DecimalPlaces = in.DecimalPlaces
	out.CustomNumFmt = in.CustomNumFmt
	out.NegRed = in.NegRed
	return out
}

